#include <bits/stdc++.h>
using namespace std;

void insert_dist(int dist, char c, unordered_map<char, int>& dist_map, int diff) {
    if (dist <= (13 + diff)) {
        dist_map[c] = abs(dist - diff);
    } else {
        dist_map[c] = 26 + diff - dist;
    }
}

void solve(istream& input, ostream& output) {
    unordered_map<char, int> dist_a;
    unordered_map<char, int> dist_c;
    unordered_map<char, int> dist_t;
    unordered_map<char, int> dist_g;

    string alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    for (int i = 0; i < (int)alphabet.size(); ++i) {
        char c = alphabet[i];
        int dist = i;
        insert_dist(dist, c, dist_a, 0);
        insert_dist(dist, c, dist_c, 2);
        if (dist <= 6) {
            dist_t[c] = 7 + dist;
        } else {
            dist_t[c] = abs(dist - 19);
        }
        insert_dist(dist, c, dist_g, 6);
    }

    string line;
    getline(input, line);
    int n = stoi(line);

    getline(input, line);
    string s = line;
    // trim
    while (!s.empty() && isspace((unsigned char)s.back())) s.pop_back();
    while (!s.empty() && isspace((unsigned char)s.front())) s.erase(s.begin());

    vector<char> char_vec(s.begin(), s.end());
    int min_sum = -1;
    for (int i = 0; i < n - 3; ++i) {
        int sum = dist_a[char_vec[i]] +
                  dist_c[char_vec[i + 1]] +
                  dist_t[char_vec[i + 2]] +
                  dist_g[char_vec[i + 3]];
        if (min_sum == -1 || sum < min_sum) {
            min_sum = sum;
        }
    }

    output << min_sum << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}

